"""Dependency-free named constants for the chess game."""


class Enum:
    def __new__(cls, value):
        for member in cls.__dict__.values():
            if isinstance(member, cls) and member.value == value:
                return member
        raise ValueError(f'{value!r} is not a valid {cls.__name__}')

    @classmethod
    def _member(cls, name, value):
        member = object.__new__(cls)
        member.name = name
        member.value = value
        return member

    def __repr__(self):
        return f'{type(self).__name__}.{self.name}'

"""Shared primitives: colors, squares and board geometry.

Squares are ``(row, col)`` tuples; row 0 is rank 8 and col 0 is file ``a``.
"""
from .legacy_enum import Enum

BOARD_SIZE = 8
FILES = 'abcdefgh'
PROMOTION_LETTERS = 'qrbn'


class Color(Enum):

    @property
    def opposite(self):
        return Color.BLACK if self is Color.WHITE else Color.WHITE

    @property
    def label(self):
        return 'White' if self is Color.WHITE else 'Black'

    @property
    def pawn_direction(self):
        return -1 if self is Color.WHITE else 1

    @property
    def pawn_start_row(self):
        return 6 if self is Color.WHITE else 1

    @property
    def home_row(self):
        return 7 if self is Color.WHITE else 0

    @property
    def castling_letters(self):
        """(king side, queen side) letters as used in castling rights."""
        return ('K', 'Q') if self is Color.WHITE else ('k', 'q')


Color.WHITE = Color._member('WHITE', 'w')
Color.BLACK = Color._member('BLACK', 'b')


def inside(square):
    row, col = square
    return 0 <= row < BOARD_SIZE and 0 <= col < BOARD_SIZE


def square_name(square):
    row, col = square
    return f'{FILES[col]}{BOARD_SIZE - row}'


def parse_square(text):
    """Turn ``"e4"`` into ``(4, 4)``; return ``None`` for invalid text."""
    if len(text) != 2 or text[0] not in FILES or text[1] not in '12345678':
        return None
    return (BOARD_SIZE - int(text[1]), FILES.index(text[0]))

from collections import namedtuple

from .legacy_enum import Enum
from .common import square_name


class MoveFlag(Enum):
    pass


MoveFlag.NORMAL = MoveFlag._member('NORMAL', '')
MoveFlag.EN_PASSANT = MoveFlag._member('EN_PASSANT', 'ep')
MoveFlag.CASTLE = MoveFlag._member('CASTLE', 'castle')


class MoveRequest(namedtuple('MoveRequestBase', 'origin target promotion')):
    """What the player typed, before it is matched against the legal moves."""
    __slots__ = ()

    def __new__(cls, origin, target, promotion=''):
        return super().__new__(cls, origin, target, promotion)


class Move(namedtuple('MoveBase', 'origin target promotion flag')):
    __slots__ = ()

    def __new__(cls, origin, target, promotion='', flag=MoveFlag.NORMAL):
        return super().__new__(cls, origin, target, promotion, flag)

    def matches(self, request):
        return (self.origin, self.target, self.promotion) == (request.origin, request.target, request.promotion)

    def __str__(self):
        return square_name(self.origin) + square_name(self.target) + self.promotion

"""Piece behavior: every piece knows which squares it attacks and which moves it can make."""
from abc import ABCMeta, abstractmethod
from .common import PROMOTION_LETTERS, Color, inside
from .move import Move, MoveFlag
KNIGHT_STEPS = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
STRAIGHT = [(-1, 0), (1, 0), (0, -1), (0, 1)]
DIAGONAL = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
KING_STEPS = STRAIGHT + DIAGONAL


class Piece(metaclass=ABCMeta):
    """Immutable piece; positions live on the board, not on the piece."""

    def __init__(self, color):
        self.color = color

    @property
    def symbol(self):
        return self.kind.upper() if self.color is Color.WHITE else self.kind

    def __eq__(self, other):
        return type(self) is type(other) and self.color is other.color

    def __hash__(self):
        return hash((type(self), self.color))

    def __repr__(self):
        return f'{type(self).__name__}({self.color.name})'

    @abstractmethod
    def attacks(self, board, origin):
        """Squares this piece attacks (may include occupied squares of either color)."""

    def moves(self, board, origin, state):
        for target in self.attacks(board, origin):
            if self._can_land_on(board, target):
                yield Move(origin, target)

    def _can_land_on(self, board, target):
        occupant = board.piece_at(target)
        return occupant is None or (occupant.color is not self.color and (not isinstance(occupant, King)))


class LeaperPiece(Piece):

    def attacks(self, board, origin):
        row, col = origin
        for d_row, d_col in self.STEPS:
            square = (row + d_row, col + d_col)
            if inside(square):
                yield square


class SlidingPiece(Piece):

    def attacks(self, board, origin):
        row, col = origin
        for d_row, d_col in self.DIRECTIONS:
            square = (row + d_row, col + d_col)
            while inside(square):
                yield square
                if board.piece_at(square) is not None:
                    break
                square = (square[0] + d_row, square[1] + d_col)


class Knight(LeaperPiece):
    kind = 'n'
    STEPS = KNIGHT_STEPS


class Bishop(SlidingPiece):
    kind = 'b'
    DIRECTIONS = DIAGONAL


class Rook(SlidingPiece):
    kind = 'r'
    DIRECTIONS = STRAIGHT


class Queen(SlidingPiece):
    kind = 'q'
    DIRECTIONS = STRAIGHT + DIAGONAL


class King(LeaperPiece):
    kind = 'k'
    STEPS = KING_STEPS

    def moves(self, board, origin, state):
        yield from super().moves(board, origin, state)
        yield from self._castling_moves(board, origin, state)

    def _castling_moves(self, board, origin, state):
        home = self.color.home_row
        if origin != (home, 4) or board.is_in_check(self.color):
            return
        enemy = self.color.opposite
        rook = Rook(self.color)
        short_right, long_right = self.color.castling_letters

        def free_and_safe(empty_cols, crossed_cols):
            return all((board.piece_at((home, c)) is None for c in empty_cols)) and (not any((board.is_attacked((home, c), enemy) for c in crossed_cols)))
        if short_right in state.castling_rights and board.piece_at((home, 7)) == rook and free_and_safe([5, 6], [5, 6]):
            yield Move(origin, (home, 6), flag=MoveFlag.CASTLE)
        if long_right in state.castling_rights and board.piece_at((home, 0)) == rook and free_and_safe([1, 2, 3], [3, 2]):
            yield Move(origin, (home, 2), flag=MoveFlag.CASTLE)


class Pawn(Piece):
    kind = 'p'

    def attacks(self, board, origin):
        row, col = origin
        for d_col in (-1, 1):
            square = (row + self.color.pawn_direction, col + d_col)
            if inside(square):
                yield square

    def moves(self, board, origin, state):
        row, col = origin
        direction = self.color.pawn_direction
        ahead = (row + direction, col)
        if inside(ahead) and board.piece_at(ahead) is None:
            yield from self._pawn_moves(origin, ahead)
            two_ahead = (row + 2 * direction, col)
            if row == self.color.pawn_start_row and board.piece_at(two_ahead) is None:
                yield from self._pawn_moves(origin, two_ahead)
        enemy_pawn = Pawn(self.color.opposite)
        for target in self.attacks(board, origin):
            occupant = board.piece_at(target)
            if occupant is not None and occupant.color is not self.color and (not isinstance(occupant, King)):
                yield from self._pawn_moves(origin, target)
            elif state.en_passant == target and board.piece_at((row, target[1])) == enemy_pawn:
                yield from self._pawn_moves(origin, target, MoveFlag.EN_PASSANT)

    @staticmethod
    def _pawn_moves(origin, target, flag=MoveFlag.NORMAL):
        if target[0] in (0, 7):
            for promotion in PROMOTION_LETTERS:
                yield Move(origin, target, promotion, flag)
        else:
            yield Move(origin, target, '', flag)


PIECE_TYPES = {cls.kind: cls for cls in (Pawn, Knight, Bishop, Rook, Queen, King)}


def piece_from_symbol(symbol):
    """``"N"`` -> white knight, ``"n"`` -> black knight."""
    color = Color.WHITE if symbol.isupper() else Color.BLACK
    return PIECE_TYPES[symbol.lower()](color)

from .common import BOARD_SIZE, Color, inside
from .pieces import King, Piece, piece_from_symbol

INITIAL_ROWS = [
    'rnbqkbnr',
    'pppppppp',
    '........',
    '........',
    '........',
    '........',
    'PPPPPPPP',
    'RNBQKBNR',
]


class Board:
    """An 8x8 grid of optional pieces. Mutable, but ``copy()`` is cheap."""

    def __init__(self, grid):
        self._grid = grid

    @classmethod
    def from_rows(cls, rows):
        return cls([[None if ch == '.' else piece_from_symbol(ch) for ch in row] for row in rows])

    @classmethod
    def initial(cls):
        return cls.from_rows(INITIAL_ROWS)

    def copy(self):
        return Board([row[:] for row in self._grid])

    def piece_at(self, square):
        return self._grid[square[0]][square[1]]

    def place(self, square, piece):
        self._grid[square[0]][square[1]] = piece

    def pieces(self, color=None):
        for row in range(BOARD_SIZE):
            for col in range(BOARD_SIZE):
                piece = self._grid[row][col]
                if piece is not None and (color is None or piece.color is color):
                    yield ((row, col), piece)

    def find_king(self, color):
        for square, piece in self.pieces(color):
            if isinstance(piece, King):
                return square
        return None

    def is_attacked(self, square, by):
        return any(square in piece.attacks(self, origin) for origin, piece in self.pieces(by))

    def is_in_check(self, color):
        king = self.find_king(color)
        return True if king is None else self.is_attacked(king, color.opposite)

    def rows(self):
        """Text rows, ``.`` for empty squares (white uppercase, black lowercase)."""
        return [''.join('.' if p is None else p.symbol for p in row) for row in self._grid]

from collections import namedtuple

from .board import Board
from .common import Color, parse_square
from .move import Move, MoveFlag
from .pieces import PIECE_TYPES, King, Pawn
_ROOK_CORNERS = [((7, 7), 'K'), ((7, 0), 'Q'), ((0, 7), 'k'), ((0, 0), 'q')]

class GameState(namedtuple('GameStateBase', 'board turn castling_rights en_passant halfmove fullmove')):
    __slots__ = ()

    def __new__(cls, board, turn=Color.WHITE, castling_rights='KQkq', en_passant=None, halfmove=0, fullmove=1):
        return super().__new__(cls, board, turn, castling_rights, en_passant, halfmove, fullmove)
    'One position plus the extra rules data. ``apply`` returns a new state.'

    @classmethod
    def initial(cls):
        return cls(Board.initial())

    @classmethod
    def from_fen(cls, fen):
        parts = fen.split()
        rows = [''.join(('.' * int(ch) if ch.isdigit() else ch for ch in rank)) for rank in parts[0].split('/')]
        return cls(board=Board.from_rows(rows), turn=Color(parts[1]), castling_rights='' if parts[2] == '-' else parts[2], en_passant=None if parts[3] == '-' else parse_square(parts[3]), halfmove=int(parts[4]) if len(parts) > 4 else 0, fullmove=int(parts[5]) if len(parts) > 5 else 1)

    def apply(self, move):
        board = self.board.copy()
        (from_row, from_col), (to_row, to_col) = (move.origin, move.target)
        piece = board.piece_at(move.origin)
        captured = board.piece_at(move.target)
        board.place(move.origin, None)
        board.place(move.target, PIECE_TYPES[move.promotion](self.turn) if move.promotion else piece)
        if move.flag is MoveFlag.EN_PASSANT:
            board.place((from_row, to_col), None)
        if move.flag is MoveFlag.CASTLE:
            rook_from, rook_to = (7, 5) if to_col == 6 else (0, 3)
            board.place((to_row, rook_to), board.piece_at((to_row, rook_from)))
            board.place((to_row, rook_from), None)
        rights = self.castling_rights
        if isinstance(piece, King):
            for letter in piece.color.castling_letters:
                rights = rights.replace(letter, '')
        for corner, letter in _ROOK_CORNERS:
            if corner in (move.origin, move.target):
                rights = rights.replace(letter, '')
        en_passant = None
        if isinstance(piece, Pawn) and abs(to_row - from_row) == 2:
            en_passant = ((from_row + to_row) // 2, from_col)
        irreversible = isinstance(piece, Pawn) or captured is not None or move.flag is MoveFlag.EN_PASSANT
        return GameState(board=board, turn=self.turn.opposite, castling_rights=rights, en_passant=en_passant, halfmove=0 if irreversible else self.halfmove + 1, fullmove=self.fullmove + (1 if self.turn is Color.BLACK else 0))

"""Pure functions that apply the rules of chess to a ``GameState``."""
from .board import Board
from .common import square_name
from .game_state import GameState
from .move import Move, MoveFlag
from .pieces import Bishop, King


def pseudo_legal_moves(state):
    for origin, piece in state.board.pieces(state.turn):
        yield from piece.moves(state.board, origin, state)


def legal_moves(state):
    return [
        move
        for move in pseudo_legal_moves(state)
        if not state.apply(move).board.is_in_check(state.turn)
    ]


def is_in_check(state):
    return state.board.is_in_check(state.turn)


def insufficient_material(board):
    """Obvious dead positions: bare kings, king + one minor piece, or only
    bishops standing on the same square color."""
    others = [
        (piece, (row + col) % 2)
        for (row, col), piece in board.pieces()
        if not isinstance(piece, King)
    ]
    if not others:
        return True
    if len(others) == 1 and others[0][0].kind in 'bn':
        return True
    first_color = others[0][1]
    return all(isinstance(piece, Bishop) and shade == first_color for piece, shade in others)


def position_key(state):
    """Identity of a position for repetition counting.

    The en passant square only counts if the capture is actually legal."""
    key = f"{''.join(state.board.rows())}{state.turn.value}/{state.castling_rights}/"
    if state.en_passant is not None and any(
        m.flag is MoveFlag.EN_PASSANT for m in legal_moves(state)
    ):
        key += square_name(state.en_passant)
    return key

"""Converting between text typed by the player and moves."""
from .common import PROMOTION_LETTERS, parse_square
from .game_state import GameState
from .move import MoveRequest
from .pieces import Pawn


def parse_move(text, state):
    text = text.lower().strip().replace(' ', '')
    home = state.turn.home_row
    castle = text.replace('-', '')
    if castle in ('oo', '00'):
        return MoveRequest((home, 4), (home, 6))
    if castle in ('ooo', '000'):
        return MoveRequest((home, 4), (home, 2))
    if len(text) not in (4, 5):
        return None
    origin, target = parse_square(text[:2]), parse_square(text[2:4])
    if origin is None or target is None:
        return None
    promotion = ''
    if len(text) == 5:
        promotion = text[4]
        if promotion not in PROMOTION_LETTERS:
            return None
    elif isinstance(state.board.piece_at(origin), Pawn) and target[0] in (0, 7):
        promotion = 'q'
    return MoveRequest(origin, target, promotion)

from .board import Board

_FILE_LABELS = '    a b c d e f g h'


class BoardRenderer:
    """Draws a board as plain text."""

    def render(self, board):
        lines = ['', _FILE_LABELS, '']
        for index, row in enumerate(board.rows()):
            rank = 8 - index
            lines.append(f' {rank}  {" ".join(row)}  {rank}')
        lines += ['', _FILE_LABELS, '', 'UPPERCASE = White; lowercase = Black']
        return '\n'.join(lines)

from .legacy_enum import Enum
from . import rules
from .common import Color
from .game_state import GameState
from .move import Move, MoveRequest


class GameStatus(Enum):
    pass


GameStatus.ONGOING = GameStatus._member('ONGOING', 'ongoing')
GameStatus.CHECKMATE = GameStatus._member('CHECKMATE', 'checkmate')
GameStatus.STALEMATE = GameStatus._member('STALEMATE', 'stalemate')
GameStatus.INSUFFICIENT_MATERIAL = GameStatus._member('INSUFFICIENT_MATERIAL', 'insufficient material')
GameStatus.FIVEFOLD_REPETITION = GameStatus._member('FIVEFOLD_REPETITION', 'fivefold repetition')
GameStatus.SEVENTY_FIVE_MOVE_RULE = GameStatus._member('SEVENTY_FIVE_MOVE_RULE', '75-move rule')


class Game:
    """A game in progress: the position history, undo and end-of-game detection."""
    CLAIM_REPETITIONS = 3
    CLAIM_HALFMOVES = 100
    FORCED_REPETITIONS = 5
    FORCED_HALFMOVES = 150

    def __init__(self, state=None):
        self._history = [state or GameState.initial()]
        self._keys = [rules.position_key(self._history[0])]

    @property
    def state(self):
        return self._history[-1]

    def legal_moves(self):
        return rules.legal_moves(self.state)

    def find_move(self, request):
        return next((m for m in self.legal_moves() if m.matches(request)), None)

    def play(self, move):
        self._history.append(self.state.apply(move))
        self._keys.append(rules.position_key(self.state))

    def undo(self):
        if len(self._history) == 1:
            return False
        self._history.pop()
        self._keys.pop()
        return True

    def in_check(self):
        return rules.is_in_check(self.state)

    def repetitions(self):
        return self._keys.count(self._keys[-1])

    def can_claim_draw(self):
        return self.repetitions() >= self.CLAIM_REPETITIONS or self.state.halfmove >= self.CLAIM_HALFMOVES

    def status(self):
        if not self.legal_moves():
            return GameStatus.CHECKMATE if self.in_check() else GameStatus.STALEMATE
        if rules.insufficient_material(self.state.board):
            return GameStatus.INSUFFICIENT_MATERIAL
        if self.repetitions() >= self.FORCED_REPETITIONS:
            return GameStatus.FIVEFOLD_REPETITION
        if self.state.halfmove >= self.FORCED_HALFMOVES:
            return GameStatus.SEVENTY_FIVE_MOVE_RULE
        return GameStatus.ONGOING

    def winner(self):
        return self.state.turn.opposite if self.status() is GameStatus.CHECKMATE else None

